  {"code": "IMPLEMENTATION_BUG", "text": "The graph-database derivation of initiator and play-type records has not been validated against this question, so the pipeline needs checks before use."}
 ],
 "predicted_outcome": {
  "supported": 0.08,
  "rejected": 0.2,
  "untestable": 0.45,
  "artifact": 0.09,
  "uncertain": 0.18
 },
 "decision": "do_not_proceed",
 "design": {
  "estimand": "As posed: the difference in primary play-type gain between the closest-profile teammate and the other teammates after an absence. Minimum viable: a descriptive estimate of how often the closest-profile teammate is the largest gainer relative to the 1/k chance baseline, with uncertainty.",
  "unit": "Absence event (one absent player in one team-season), with teammates as candidate gainers within each event.",
  "sample": "Minimum viable: the 11 absence cases with their within-event teammate rankings. Do not treat the 148 spells as independent. Full test requires many more absence events than 11.",
  "power": "Not achievable with 11 cases for a ranking claim. Report the descriptive hit rate with a binomial or permutation interval against 1/k, and state that no power calculation supports a confirmatory claim.",
  "controls": "Regression to the mean (pre/post or within-player baseline), minutes and possession exposure, position, and absence reason. Profile similarity should be computed from a pre-absence window that does not overlap the outcome window.",
  "falsification": "The hypothesis is falsified if the closest-profile teammate is not the largest gainer more often than the 1/k chance baseline, using a permutation null that matches exposure and teammate set size.",
  "multiplicity": "Pre-specify one primary ranking statistic and one play-type definition. Correct for any additional play types or profile definitions with Benjamini-Hochberg or a permutation max-statistic.",
  "decision_rule": "Proceed to a confirmatory test only if the design has at least the sample of absence events needed for the pre-specified power (to be computed before analysis) and the profile, outcome, and exposure windows are pre-registered and non-overlapping. Otherwise report only the descriptive result with stated limits.",
  "data_version": "NBA 2022-23 to 2024-25 regular season and playoffs, and 2025-26 regular season and playoffs as recorded complete on 2026-11-01 (regular season complete from 2026-04-13; playoffs complete from 2026-06-21). Frozen per-game files and the derived graph-database snapshot should be hashed and recorded before analysis."
 }
